with open('/app/dataset/genealogy_trees.txt') as f:
    lines = [l.rstrip('\n') for l in f]

import csv
people = []
with open('/app/dataset/people_accounts.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        people.append((row['first_name'], row['last_name'], int(row['account_balance'])))

found = 0
not_found = []
for fn, ln, bal in people:
    # Check if on same line
    full_name = f'{fn} {ln}'
    ok = False
    for r, line in enumerate(lines):
        if full_name in line:
            ok = True
            break
    if not ok:
        # Check two consecutive lines at similar columns
        for r in range(len(lines) - 1):
            if fn in lines[r]:
                idx1 = lines[r].find(fn)
                if ln in lines[r+1]:
                    idx2 = lines[r+1].find(ln)
                    if abs(idx1 - idx2) < 15:
                        ok = True
                        break
    if ok:
        found += 1
    else:
        not_found.append(f'{fn} {ln}')

print(f'Found: {found}/{len(people)}')
if not_found:
    print('Sample not found:', not_found[:10])
"

